typedef double (*FunctionPtr)(double);

double adaptive_simpson(FunctionPtr f, double a, double b, double precision) {
    auto simpson_rule = [](FunctionPtr f, double a, double b) -> double {
        double c = (a + b) / 2.0;
        double h = (b - a) / 6.0;
        return h * (f(a) + 4.0 * f(c) + f(b));
    };

    std::function<double(FunctionPtr, double, double, double, double, double, int)> adaptive = 
        [&](FunctionPtr f, double a, double b, double fa, double fb, double fc, int depth) -> double {
        double c = (a + b) / 2.0;
        double d = (a + c) / 2.0;
        double e = (c + b) / 2.0;

        double fd = f(d);
        double fe = f(e);

        double S1 = simpson_rule(f, a, b);
        double S2 = simpson_rule(f, a, c) + simpson_rule(f, c, b);

        if (std::abs(S1 - S2) < 15.0 * precision && depth < 20) {
            return S2 + (S2 - S1) / 15.0;
        }

        if (depth >= 20) {
            return S2;
        }

        return adaptive(f, a, c, fa, fc, fd, depth + 1) + 
               adaptive(f, c, b, fc, fb, fe, depth + 1);
    };

    double c = (a + b) / 2.0;
    double fa = f(a);
    double fb = f(b);
    double fc = f(c);

    return adaptive(f, a, b, fa, fb, fc, 0);
}

